	let seedHash
	let hash = (function() {
		let seed = Math.random() * 2100000000 | 0
		let PRIME32_2 = 1883677709
		let PRIME32_3 = 2034071983
		let PRIME32_4 = 668265263
		let PRIME32_5 = 374761393

		seedHash = function(s) {
			seed = s | 0
		}

		return function(x, y) {
			let h32 = 0

			h32 = seed + PRIME32_5 | 0
			h32 += 8

			h32 += Math.imul(x, PRIME32_3)
			h32 = Math.imul(h32 << 17 | h32 >> 32 - 17, PRIME32_4)
			h32 += Math.imul(y, PRIME32_3)
			h32 = Math.imul(h32 << 17 | h32 >> 32 - 17, PRIME32_4)

			h32 ^= h32 >> 15
			h32 *= PRIME32_2
			h32 ^= h32 >> 13
			h32 *= PRIME32_3
			h32 ^= h32 >> 16

			return h32 / 2147483647
		}
	})()
	let worldSeed

	//The noise and random functions are copied from the processing.js source code; these others are polyfills made by me to avoid needing to remove all the pjs draw calls
	let currentRandom = null
	function Marsaglia(i1, i2) {
	// from http://www.math.uni-bielefeld.de/~sillke/ALGORITHMS/random/marsaglia-c
		let z = (i1 | 0) || 362436069, w = i2 || hash(521288629, z) * 2147483647 | 0

		let nextInt = function() {
			z=36969*(z&65535)+(z>>>16) & 0xFFFFFFFF
			w=18000*(w&65535)+(w>>>16) & 0xFFFFFFFF
			return ((z&0xFFFF)<<16 | w&0xFFFF) & 0xFFFFFFFF
		}

		this.nextDouble = function() {
			let i = nextInt() / 4294967296
			return i < 0 ? 1 + i : i
		}
		this.nextInt = nextInt
	}
	let randomSeed = function(seed) {
		currentRandom = (new Marsaglia(seed)).nextDouble
	}
	let random = function(min, max) {
		if (!max) {
			if (min) {
				max = min
				min = 0
			} else {
				min = 0
				max = 1
			}
		}
		return currentRandom() * (max - min) + min
	}
	let noiseProfile = { generator: undefined, octaves: 4, fallout: 0.5, seed: undefined }
	function PerlinNoise(seed) {
		let rnd = seed !== undefined ? new Marsaglia(seed) : Marsaglia.createRandomized()
		let i, j
		// http://www.noisemachine.com/talk1/17b.html
		// http://mrl.nyu.edu/~perlin/noise/
		// generate permutation
		let perm = new Uint8Array(512)
		for(i=0;i<256;++i) {
			perm[i] = i
		}
		for(i=0;i<256;++i) {
			let t = perm[j = rnd.nextInt() & 0xFF]; perm[j] = perm[i]; perm[i] = t
		}
		// copy to avoid taking mod in perm[0]
		for(i=0;i<256;++i) {
			perm[i + 256] = perm[i]
		}

		function grad3d(i,x,y,z) {
			let h = i & 15; // convert into 12 gradient directions
			let u = h<8 ? x : y,
				v = h<4 ? y : h===12||h===14 ? x : z
			return ((h&1) === 0 ? u : -u) + ((h&2) === 0 ? v : -v)
		}

		function grad2d(i,x,y) {
			let v = (i & 1) === 0 ? x : y
			return (i&2) === 0 ? -v : v
		}

		function grad1d(i,x) {
			return (i&1) === 0 ? -x : x
		}

		function lerp(t,a,b) {
			return a + t * (b - a)
		}

		this.noise3d = function(x, y, z) {
			let X = Math.floor(x) & 255, Y = Math.floor(y) & 255, Z = Math.floor(z) & 255
			x -= Math.floor(x); y -= Math.floor(y); z -= Math.floor(z)
			let fx = (3-2*x)*x*x, fy = (3-2*y)*y*y, fz = (3-2*z)*z*z
			let p0 = perm[X]+Y, p00 = perm[p0] + Z, p01 = perm[p0 + 1] + Z,
				p1 = perm[X + 1] + Y, p10 = perm[p1] + Z, p11 = perm[p1 + 1] + Z
			return lerp(fz,
				lerp(fy, lerp(fx, grad3d(perm[p00], x, y, z), grad3d(perm[p10], x-1, y, z)),
					lerp(fx, grad3d(perm[p01], x, y-1, z), grad3d(perm[p11], x-1, y-1,z))),
				lerp(fy, lerp(fx, grad3d(perm[p00 + 1], x, y, z-1), grad3d(perm[p10 + 1], x-1, y, z-1)),
					lerp(fx, grad3d(perm[p01 + 1], x, y-1, z-1), grad3d(perm[p11 + 1], x-1, y-1,z-1))))
		}

		this.noise2d = function(x, y) {
			let X = Math.floor(x)&255, Y = Math.floor(y)&255
			x -= Math.floor(x); y -= Math.floor(y)
			let fx = (3-2*x)*x*x, fy = (3-2*y)*y*y
			let p0 = perm[X]+Y, p1 = perm[X + 1] + Y
			return lerp(fy,
				lerp(fx, grad2d(perm[p0], x, y), grad2d(perm[p1], x-1, y)),
				lerp(fx, grad2d(perm[p0 + 1], x, y-1), grad2d(perm[p1 + 1], x-1, y-1)))
		}

		this.noise1d = function(x) {
			let X = Math.floor(x)&255
			x -= Math.floor(x)
			let fx = (3-2*x)*x*x
			return lerp(fx, grad1d(perm[X], x), grad1d(perm[X+1], x-1))
		}
	}
	let noiseSeed = function(seed) {
		noiseProfile.seed = seed
		noiseProfile.generator = new PerlinNoise(noiseProfile.seed)
	}
	let noise = function(x, y, z) {
		let generator = noiseProfile.generator
		let effect = 1, k = 1, sum = 0
		for(let i = 0; i < noiseProfile.octaves; ++i) {
			effect *= noiseProfile.fallout
			switch (arguments.length) {
				case 1:
					sum += effect * (1 + generator.noise1d(k*x))/2; break
				case 2:
					sum += effect * (1 + generator.noise2d(k*x, k*y))/2; break
				case 3:
					sum += effect * (1 + generator.noise3d(k*x, k*y, k*z))/2; break
			}
			k *= 2
		}
		return sum
	}

	let caveNoise
	// Copied and modified from https://github.com/blindman67/SimplexNoiseJS
	function openSimplexNoise(clientSeed) {
		const SQ4 = 2
		const toNums = function(s) { return s.split(",").map(function(s) { return new Uint8Array(s.split("").map(function(v) { return Number(v) })) }) }
		const decode = function(m, r, s) { return new Int8Array(s.split("").map(function(v) { return parseInt(v, r) + m })) }
		const toNumsB32 = function(s) { return s.split(",").map(function(s) { return parseInt(s, 32) }) }
		const NORM_3D = 1.0 / 206.0
		const SQUISH_3D = 1 / 3
		const STRETCH_3D = -1 / 6
		var base3D = toNums("0000110010101001,2110210120113111,110010101001211021012011")
		const gradients3D = decode(-11, 23, "0ff7mf7fmmfffmfffm07f70f77mm7ff0ff7m0f77m77f0mf7fm7ff0077707770m77f07f70")
		var lookupPairs3D = function() { return new Uint16Array(toNumsB32("0,2,1,1,2,2,5,1,6,0,7,0,10,2,12,2,41,1,45,1,50,5,51,5,g6,0,g7,0,h2,4,h6,4,k5,3,k7,3,l0,5,l1,5,l2,4,l5,3,l6,4,l7,3,l8,d,l9,d,la,c,ld,e,le,c,lf,e,m8,k,ma,i,p9,l,pd,n,q8,k,q9,l,15e,j,15f,m,16a,i,16e,j,19d,n,19f,m,1a8,f,1a9,h,1aa,f,1ad,h,1ae,g,1af,g,1ag,b,1ah,a,1ai,b,1al,a,1am,9,1an,9,1bg,b,1bi,b,1eh,a,1el,a,1fg,8,1fh,8,1qm,9,1qn,9,1ri,7,1rm,7,1ul,6,1un,6,1vg,8,1vh,8,1vi,7,1vl,6,1vm,7,1vn,6")) }
		var p3D = decode(-1, 5, "112011210110211120110121102132212220132122202131222022243214231243124213241324123222113311221213131221123113311112202311112022311112220342223113342223311342223131322023113322023311320223113320223131322203311322203131")
		const setOf = function(count) { var a = [],i = 0; while (i < count) { a.push(i++) } return a }
		const doFor = function(count, cb) { var i = 0; while (i < count && cb(i++) !== true) {} }

		function shuffleSeed(seed,count){
			seed = seed * 1664525 + 1013904223 | 0
			count -= 1
			return count > 0 ? shuffleSeed(seed, count) : seed
		}
		const types = {
			_3D : {
				base : base3D,
				squish : SQUISH_3D,
				dimensions : 3,
				pD : p3D,
				lookup : lookupPairs3D,
			}
		}

		function createContribution(type, baseSet, index) {
			var i = 0
			const multiplier = baseSet[index ++]
			const c = { next : undefined }
			while(i < type.dimensions) {
				const axis = ("xyzw")[i]
				c[axis + "sb"] = baseSet[index + i]
				c["d" + axis] = - baseSet[index + i++] - multiplier * type.squish
			}
			return c
		}

		function createLookupPairs(lookupArray, contributions){
			var i
			const a = lookupArray()
			const res = new Map()
			for (i = 0; i < a.length; i += 2) { res.set(a[i], contributions[a[i + 1]]); }
			return res
		}

		function createContributionArray(type) {
			const conts = []
			const d = type.dimensions
			const baseStep = d * d
			var k, i = 0
			while (i < type.pD.length) {
				const baseSet = type.base[type.pD[i]]
				let previous, current
				k = 0
				do {
					current = createContribution(type, baseSet, k)
					if (!previous) { conts[i / baseStep] = current; }
					else { previous.next = current; }
					previous = current
					k += d + 1
				} while(k < baseSet.length)

				current.next = createContribution(type, type.pD, i + 1)
				if (d >= 3) { current.next.next = createContribution(type, type.pD, i + d + 2) }
				if (d === 4) { current.next.next.next = createContribution(type, type.pD, i + 11) }
				i += baseStep
			}
			const result = [conts, createLookupPairs(type.lookup, conts)]
			type.base = undefined
			type.lookup = undefined
			return result
		}

		let temp = createContributionArray(types._3D)
		const contributions3D = temp[0], lookup3D = temp[1]
		const perm = new Uint8Array(256)
		const perm3D = new Uint8Array(256)
		const source = new Uint8Array(setOf(256))
		var seed = shuffleSeed(clientSeed, 3)
		doFor(256, function(i) {
			i = 255 - i
			seed = shuffleSeed(seed, 1)
			var r = (seed + 31) % (i + 1)
			r += r < 0 ? i + 1 : 0
			perm[i] = source[r]
			perm3D[i] = (perm[i] % 24) * 3
			source[r] = source[i]
		})
		base3D = undefined
		lookupPairs3D = undefined
		p3D = undefined

		return function(x, y, z) {
			const pD = perm3D
			const p = perm
			const g = gradients3D
			const stretchOffset = (x + y + z) * STRETCH_3D
			const xs = x + stretchOffset, ys = y + stretchOffset, zs = z + stretchOffset
			const xsb = Math.floor(xs), ysb = Math.floor(ys), zsb = Math.floor(zs)
			const squishOffset	= (xsb + ysb + zsb) * SQUISH_3D
			const dx0 = x - (xsb + squishOffset), dy0 = y - (ysb + squishOffset), dz0 = z - (zsb + squishOffset)
			const xins = xs - xsb, yins = ys - ysb, zins = zs - zsb
			const inSum = xins + yins + zins
			var c = lookup3D.get(
				(yins - zins + 1) |
				((xins - yins + 1) << 1) |
				((xins - zins + 1) << 2) |
				(inSum << 3) |
				((inSum + zins) << 5) |
				((inSum + yins) << 7) |
				((inSum + xins) << 9)
			)
			var i, value = 0
			while (c !== undefined) {
				const dx = dx0 + c.dx, dy = dy0 + c.dy, dz = dz0 + c.dz
				let attn = 2 - dx * dx - dy * dy - dz * dz
				if (attn > 0) {
					i = pD[(((p[(xsb + c.xsb) & 0xFF] + (ysb + c.ysb)) & 0xFF) + (zsb + c.zsb)) & 0xFF]
					attn *= attn
					value += attn * attn * (g[i++] * dx + g[i++] * dy + g[i] * dz)
				}
				c = c.next
			}
			return value * NORM_3D + 0.5
		}
	}

	let PVector = function(x, y, z) {
		this.x = x
		this.y = y
		this.z = z
		this.set = function(x, y, z) {
			if (y === undefined) {
				this.x = x.x
				this.y = x.y
				this.z = x.z
			} else {
				this.x = x
				this.y = y
				this.z = z
			}
		}
		this.normalize = function() {
			let mag = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z)
			this.x /= mag
			this.y /= mag
			this.z /= mag
		}
		this.add = function(v) {
			this.x += v.x
			this.y += v.y
			this.z += v.z
		}
		this.mult = function(m) {
			this.x *= m
			this.y *= m
			this.z *= m
		}
	}
	let fill = function(r, g, b) {
		if (g === undefined) {
			g = r
			b = r
		}
		ctx.fillStyle = "rgb(" + r + ", " + g + ", " + b + ")"
	}
	let stroke = function(r, g, b) {
		if (g === undefined) {
			g = r
			b = r
		}
		ctx.strokeStyle = "rgb(" + r + ", " + g + ", " + b + ")"
	}
	let line = function(x1, y1, x2, y2) {
		ctx.moveTo(x1, y1)
		ctx.lineTo(x2, y2)
	}
	function text(txt, x, y, h) {
		h = h || 0

		let lines = txt.split("\n")
		for (let i = 0; i < lines.length; i++) {
			ctx.fillText(lines[i], x, y + h * i)
		}
	}
	function textSize(size) {
		// Pirata One: fuente principal de menus y HUD.  El bloque de
		// debug (FPS/coords en hud()) pone su fuente a mano para
		// mantenerse en Poppins, que se lee mejor en numeros pequenos.
		ctx.font = size + 'px "Pirata One"'
	}
	let strokeWeight = function(num) {
		ctx.lineWidth = num
	}
	const ARROW = "arrow"
	const HAND = "pointer"
	const CROSS = "crosshair"
	let cursor = function(type) {
		canvas.style.cursor = type
	}
	randomSeed(Math.random() * 10000000 | 0)

	async function createDatabase() {
		return await new Promise(async (resolve, reject) => {
			let request = window.indexedDB.open("MineKhan", 1)

			request.onupgradeneeded = function(event) {
				let DB = event.target.result
				// Worlds will contain and ID containing the timestamp at which the world was created, a "saved" timestamp,
				// and a "data" string that's identical to the copy/paste save string
				let store = DB.createObjectStore("worlds", { keyPath: "id" })
				store.createIndex("id", "id", { unique: true })
				store.createIndex("data", "data", { unique: false })
			}

			request.onsuccess = function(e) {
				resolve(request.result)
			}

			request.onerror = function(e) {
				console.error(e)
				reject(e)
			}
		})
	}
	async function loadFromDB(id) {
		return await new Promise(async (resolve, reject) => {
			let db = await createDatabase()
			let trans = db.transaction("worlds", "readwrite")
			let store = trans.objectStore("worlds")
			let req = id ? store.get(id) : store.getAll()
			req.onsuccess = function(e) {
				resolve(req.result)
				db.close()
			}
			req.onerror = function(e) { 
				resolve(null)
				db.close()
			}
		})
	}
	async function saveToDB(id, data) {
		return new Promise(async (resolve, reject) => {
			let db = await createDatabase()
			let trans = db.transaction("worlds", "readwrite")
			let store = trans.objectStore("worlds")
			let req = store.put({ id: id, data: data })
			req.onsuccess = function() {
				resolve(req.result)
			}
			req.onerror = function(e) {
				reject(e)
			}
		})
	}
	async function deleteFromDB(id) {
		return new Promise(async (resolve, reject) => {
			let db = await createDatabase()
			let trans = db.transaction("worlds", "readwrite")
			let store = trans.objectStore("worlds")
			let req = store.delete(id)
			req.onsuccess = function() {
				resolve(req.result)
			}
			req.onerror = function(e) {
				reject(e)
			}
		})
	}

	// Worlds store the generator settings they were created with, so they
	// always regenerate EXACTLY as saved, even after parameter changes.
	function applySavedSettings(settings) {
		if (!settings) {
			return
		}
		if (settings.river) {
			Object.assign(riverSettings, settings.river)
		}
		if (settings.biome) {
			Object.assign(biomeSettings, settings.biome)
		}
		if (settings.generator) {
			Object.assign(generator, settings.generator)
		}
	}

	// Deterministic terrain sample: probes at FIXED coordinates (near the
	// world origin, independent of spawn/player position), so save-time and
	// load-time fingerprints are directly comparable pure-math values.
	function terrainFingerprint() {
		return worldSeed.toString(36) + ":"
			+ terrainHeight(8, 8) + ","
			+ terrainHeight(72, 8) + ","
			+ terrainHeight(8, -56) + ","
			+ terrainHeight(-120, 136)
	}

	function save() {
		let record = {
			id: world.id,
			edited: Date.now(),
			name: world.name,
			version: version,
			code: world.getSaveString(),
			mode: world.mode || "creative",
			main: inventory.main,
			hotbar: inventory.hotbar,
			// Equipo y stats de supervivencia (records viejos no los traen)
			equip: inventory.equip || [0, 0, 0, 0, 0],
			hunger: hunger,
			stamina: stamina,
			settings: {
				river: Object.assign({}, riverSettings),
				biome: Object.assign({}, biomeSettings),
				generator: Object.assign({}, generator)
			},
			fp: terrainFingerprint(),
			spawn: world.spawn ? { x: world.spawn.x, y: world.spawn.y, z: world.spawn.z } : null,
			// Las vacas (id, stats, genoma, rumbo, bioma) viajan en el
			// record del mundo en IndexedDB.  El codigo de guardar/copiar
			// (getSaveString) NO las incluye todavia: solo este record.
			identidades: window.VXLIdentidades && window.VXLIdentidades.exportar
				? window.VXLIdentidades.exportar()
				: []
		}
		// Keep the in-memory menu record fresh too, so a same-session
		// load never reads a stale code string
		worlds[world.id] = record
		saveToDB(world.id, record).then(() => world.edited = Date.now()).catch(e => console.error(e))
	}

	// Expose these functions to the global scope for debugging
	win.saveToDB = saveToDB
	win.loadFromDB = loadFromDB
	win.createDatabase = createDatabase
	win.deleteFromDB = deleteFromDB

	//globals
	//{
	let version = "0.1 Alpha"
	let reach = 100 // Max distance player can place or break blocks
	// Alcance del rayo contra ENTIDADES (las vacas): mas corto a proposito,
	// el marco amarillo + panel solo tienen sentido mirando al animal de cerca.
	const ALC_ENTIDAD = 16
	let sky = [0.33, 0.54, 0.72] // 0 to 1 RGB color scale
	let superflat = false
	let trees = true
	let caves = true

	// ------------------------------------------------------------------
	// Isla del menu principal (fondo en vivo).  menuIsla es el gate: solo
	// mientras esta activa, rawColumnGen() devuelve la columna-isla y la
	// distancia de render/niebla es MENU_RD.  Se apaga al crear o cargar
	// una partida, antes de generar ningun chunk.
	// ------------------------------------------------------------------
	let menuIsla = false
	let menuWorld = null // World del menu, cacheado para no regenerar al volver
	const ISLA = { x: 0, z: 0, radio: 30, altura: 10, orilla: 6 }
	const MENU_RD = 3 // 11x11 chunks en la ventana, niebla a 48 bloques
	// RenderDistance efectiva: la del jugador, salvo en el menu.
	function rdActiva() {
		return menuIsla ? MENU_RD : settings.renderDistance
	}

	let blockIds = {}
	blockData.forEach(block => blockIds[block.name] = block.id)
	win.blockData = blockData
	win.blockIds = blockIds

	let currentFov

	// Configurable and savable settings
	let settings = {
		renderDistance: 10,
		fov: 70, // Field of view in degrees
		mouseSense: 100 // Mouse sensitivity as a percentage of the default
	}
	// El PRIMER frame no se pinta hasta que los ajustes esten aplicados:
	// si llegan despues de pintar (la DB es async), el FOV salta en mitad
	// de la isla del menu un segundo o mas despues de cargar.
	let ajustesListos = false
	// Los ajustes ya estan fijados (espejo, DB o timeout): despues de eso NO
	// se releen, porque initWorldsMenu() se llama tambien al salir de
	// partidas y una lectura tardia podria pisar valores recien guardados
	// (y mover el FOV en pantalla).
	let ajustesFijados = false
	// Espejo sincrono en localStorage: cubre el FOV/distancia/etc. ANTES de
	// cualquier lectura async, asi el primer frame ya sale con ellos y la
	// DB (que luego escribe lo mismo) no puede provocar ningun salto.
	try {
		let guardado = win.localStorage.getItem("voxeland.settings")
		let espejo = guardado ? JSON.parse(guardado) : null
		if (espejo && typeof espejo === "object") {
			Object.assign(settings, espejo)
			ajustesFijados = true
			ajustesListos = true
		}
	} catch (e) {
		console.error(e)
	}
	let locked = true
	let generatedChunks
	let mouseX, mouseY, mouseDown
	let width = window.innerWidth
	let height = window.innerHeight

	if (height === 400) alert("Canvas is too small. Click the \"Settings\" button to the left of the \"Vote Up\" button under the editor and change the height to 600.")

	let generator = {
		height: 80, // Height of the hills
		smooth: 0.01, // Smoothness of the terrain
		extra: 30, // Extra height added to the world.
		caveSize: 0.00 // Redefined right above where it's used
	}
	// ------------------------------------------------------------------
	// USER-EDITABLE MASTER PARAMETERS: all generation values live in
	// biome-params.js (window.WORLD_PARAMS) — every one has a fallback
	// here so the engine runs even without that file. New worlds use
	// these values; old worlds keep their saved snapshot.
	// ------------------------------------------------------------------
	let W = (typeof window !== "undefined" && window.WORLD_PARAMS) || {}
	function wp(section, key, fallback) {
		if (W[section] && W[section][key] !== undefined) {
			return W[section][key]
		}
		return fallback
	}
	generator.smooth = wp("terreno", "frecuenciaOndulacion", 0.01)

	// River / lake generation. Exposed on the window so it can be tuned
	// live from the console; affects newly generated chunks. Rivers are
	// biome FRONTIERS: the channel is carved along the biome border
	// contours (see rawColumnGen), seas are valleys flooded below the
	// sea level.
	let riverSettings = {
		seaLevel: wp("agua", "nivelMar", 62), // Water surface height (valleys below this flood into seas/lakes)
		maxDepth: wp("rios", "profundidad", 5), // Border-river water depth cap (seas are naturally much deeper)
		riverTerraces: wp("rios", "terrazas", 5), // Terraced bed: flat plateaus with 1-block steps (terrain staircase pattern)
		coastWobble: wp("agua", "wobbleCosta", 0.3), // Coast irregularity at the waterline (small: never creates coast steps)
		coastBand: wp("agua", "bandaWobble", 4), // How far from sea level the wobble reaches (plains live above it)
		coastScale: wp("agua", "escalaWobble", 0.12), // Coast irregularity frequency
		seaShelfDepth: wp("agua", "estanteMarino", 3), // Uniform sunken shelf: every sea/lake bottom at this constant depth
		coastShelf: wp("agua", "shelfCosta", 12), // Coast shelf: blocks above water compressed for gradual coasts
		coastFlatness: wp("agua", "planicieCosta", 0.25), // Waterline slope factor in the shelf (lower = flatter coasts)
		lakeDepth: wp("lagos", "profundidad", 1), // Lake water depth below the sea level (shallow natural ponds)
		lakeScale: wp("lagos", "escala", 0.007), // Interior-lake noise frequency
		lakeThreshold: wp("lagos", "umbral", 0.3), // Lake noise value where the bowl starts (higher = fewer, smaller lakes)
		lakeEdge: wp("lagos", "borde", 0.2), // Shore blend width in noise units (degradé ring)
			lakeHeightBand: wp("lagos", "banda", 5), // Linear fade width: hFade=0 at datum+band (hills untouched), 1 at datum (the hondonadas) — slope gain of the carve is (gen-lakeFloor)/band
		lakeDesertFade: wp("lagos", "fadeDesierto", 0.08), // Lakes fade out BEFORE crossing the desert threshold: gone at the frontier
		swampLakeBoost: wp("pantano", "boostLagos", 1.9), // Ponds are far more frequent in swamps (scales the lake-noise value)
		forestLakeBoost: wp("bosque", "boostLagos", 1.5) // ... then in forests (plains = 1.0)
	}
	win.riverSettings = riverSettings
	let riverNoise = null
	let lakeNoise = null

	// Safe spawn: scan outward in a spiral for a dry column above sea level
	// (with the sea at 60 the default (8, 8) spot is often under water).
	// Falls back to dropping into the sea from above, which the water's
	// fall-damage cancellation makes harmless.
	function spawnHeight() {
		if (superflat) {
			return { x: 8, y: 6, z: 8 }
		}
		for (let radius = 0; radius <= 128; radius += 8) {
			for (let dx = -radius; dx <= radius; dx += 8) {
				for (let dz = -radius; dz <= radius; dz += 8) {
					if (radius !== 0 && Math.abs(dx) !== radius && Math.abs(dz) !== radius) {
						continue
					}
					let x = 8 + dx
					let z = 8 + dz
					let y = terrainHeight(x, z) + 2
					if (y > riverSettings.seaLevel + 1) {
						return { x: x, y: y, z: z }
					}
				}
			}
		}
		// All water nearby: drop from above the sea (water cancels fall damage)
		return { x: 8, y: riverSettings.seaLevel + 20, z: 8 }
	}

	// ------------------------------------------------------------------
	// Biomes (vanilla-style large zones). Three very-low-frequency climate
	// channels: erosion shapes the relief CONTINUOUSLY (high erosion =
	// smooth flat plains, low erosion = tall mountains) so biome borders
	// never cliff; temperature and humidity only pick the visual biome
	// (surface blocks and tree density), exactly like modern Minecraft.
	// Zones are large (climateScale ~1400-block cells) and the rivers ARE
	// the biome frontiers: the channels are carved exactly along the
	// threshold contours (borderDistanceAt + rawColumnGen).
	// ------------------------------------------------------------------
	let biomeSettings = {
		climateScale: wp("clima", "escala", 0.0007), // Biome size: lower = larger biomes (zones ~1000-2500 blocks across)
		humidityScale: wp("clima", "escalaHumedad", 0.6), // Extra scale for the humidity channel: forests are broader than the rest
		climateSpread: wp("clima", "contraste", 0.3), // Contrast: stretches clustered Perlin values to the full range
		biomeReliefEffect: wp("clima", "doblezRelieve", 0.04), // Border bending around relief contours (tiny: the frontier lines stay fluid, without teeth)
		reliefBand: wp("clima", "bandaRelieve", 0.16), // Climate-value band around the thresholds where relief may bend borders
		terrainRoughness: wp("terreno", "rugosidad", 0.25), // Small-detail octaves: 0 = pure smooth waves, 1 = original feel
		plainsAmp: wp("terreno", "ampLlanura", 10), // Terrain amplitude where erosion is high (clearly flat plains)
		mountainAmp: wp("terreno", "ampMontana", 80), // Terrain amplitude where erosion is low (cubic curve: mountains only where erosion is genuinely low)
		plainsBase: wp("terreno", "datum", 71), // Ground datum: the general terrain sits ~10 blocks above the water level
		mountainBase: wp("terreno", "datumMontana", 71), // Mountains rise from the same datum
		desertTemp: wp("clima", "tempDesierto", 0.55), // Temperature at/above which deserts generate (global quantile)
		forestHumidity: wp("clima", "humBosque", 0.48), // Humidity at/above which forests generate (global quantile)
		swampHumidity: wp("clima", "humPantano", 0.53), // Swamps: humid flat lowlands — the wetland biome
		swampFlatness: wp("pantano", "planicieMin", 0.55), // Minimum erosion (flat ground) for a swamp
		swampFlat: wp("pantano", "aplanado", 0.25), // Swamp terrain compression toward the waterline (broad shallow flats)
		swampFlattenRamp: wp("pantano", "rampa", 0.08), // Humidity width of the flattening ramp: how fast the swamp reaches full flat inside the biome
		desertDryness: wp("clima", "sequedadDesierto", 0.35), // Subtropical drying: heat suppresses humidity (coherent deserts, no forest slicing)
		desertTreeChance: wp("desierto", "arboles", 0),
		forestTreeChance: wp("bosque", "arboles", 0.02),
		swampTreeChance: wp("pantano", "arboles", 0.01),
		plainsTreeChance: wp("llanuras", "arboles", 0.002),
		weedDensity: wp("vegetacion", "densidad", 0.3),
		weedDensityByBiome: wp("vegetacion", "densidadPorBioma", null), // Per-biome weed density (biomeAt keys); null/missing keys fall back to weedDensity
		weedTall: wp("vegetacion", "altas", 0.175),
		peakHeight: wp("terreno", "alturaPicos", 95), // Tall mountains get stone peaks above this height
		beach: wp("playas", "activas", true), // Automatic sand beaches in the coast shelf band
		borderRiverWidth: wp("rios", "ancho", 18), // Border-river width in blocks at sea level (constant: the edge is the pure meander curve)
		borderValleyMin: wp("rios", "valleMin", 20), // Minimum frontier-valley half-width (gentle meadow banks)
		borderValleyMax: wp("rios", "valleMax", 110), // Valley half-width cap (mountain crossings)
		borderValleySlope: wp("rios", "pendiente", 0.38), // Cap on how steeply the valley walls rise per block
		beachWidth: wp("playas", "ancho", 4), // Sand band above the waterline (coasts and river shores alike)
		beachFlatness: wp("playas", "planicie", 0.25), // Height compression inside the sand band (same as the coast)
		// --- Shape field: domain warping, continents, ridges, river network ---
		warpScale: wp("continentes", "escalaWarp", 1 / 220), // Domain-warp frequency: lower = broader, gentler twists
		warpStrength: wp("continentes", "fuerzaWarp", 35), // Domain-warp amplitude in blocks (what de-blobs coastlines)
		continentScale: wp("continentes", "escala", 1 / 420), // Continentalness frequency: lower = bigger continents and oceans
		continentGain: wp("continentes", "ganancia", 2.6), // Contrast of the continentalness channel
		continentBias: wp("continentes", "sesgo", 0.35), // Land/ocean balance: higher = more land
		continentCurve: wp("continentes", "curva", [ [-1, -34], [-0.5, -22], [-0.2, -9], [-0.05, -1], [0.05, -1], [0.3, 2], [0.6, 6], [1, 11] ]), // Continentalness -> height offset from the datum. Below -9 the land is under the waterline (oceans), around 0 it is the datum (plains), high values are inland plateaus
		roughScale: wp("montañas", "escalaRugosidad", 1 / 260), // Plains-vs-rough-country frequency
		roughLo: wp("montañas", "rugosidadMin", -0.6), // Roughness where the mountain skirt STARTS: far down, so ranges rise gently from the plains (a narrow gate here put walls at the massif foot)
		roughHi: wp("montañas", "rugosidadMax", 0.25), // Roughness noise where it is fully rough
		ridgeScale: wp("montañas", "escalaCresta", 1 / 350), // Mountain crest frequency: lower = broader ranges
		ridgeSharp: wp("montañas", "agudeza", 1.2), // Peak width gain: how much of the positive noise lifts. Peaks are rounded domes, never ridges
		ridgeBase: wp("montañas", "baseCresta", 8), // Height of the mountain massif before the crests
		mountainHeight: wp("montañas", "altura", 30), // Extra height of the crests above the massif
		ridgeMaskC0: wp("montañas", "continenteMin", 0.25), // Continentalness where mountains start inland
		ridgeMaskC1: wp("montañas", "continenteMax", 0.8), // ... where the ranges are at full strength
		ridgeRough0: wp("montañas", "rugosidadCrestaMin", 0.65), // Roughness where crests start appearing
		ridgeRough1: wp("montañas", "rugosidadCrestaMax", 1), // Roughness where crests are at full strength
		ridgeErosionLo: wp("montañas", "erosionMin", 0.35), // Erosion at/below which the ranges are at full strength
		ridgeErosionHi: wp("montañas", "erosionMax", 0.6), // Erosion at/above which the ranges are gone (only genuinely low-erosion country gets mountains, so /locate mountains stays truthful)
		riverNetworkScale: wp("rios", "escalaRed", 1 / 450), // River-network frequency: lower = longer, sparser rivers
		riverNetworkCore: wp("rios", "nucleoRed", 0.005), // Noise value inside the channel (full carving strength)
		riverNetworkWidth: wp("rios", "anchoRed", 0.4), // Carve fade band in noise units: wide = gentle river valleys, never canyon knife walls. 0.4 is the narrowest band that keeps rm high enough along the thread so mountain crossings still flood (0 gaps), without ballooning lowland rivers
		riverHigh0: wp("rios", "altaMin", 16), // Height above the waterline where rivers start fading out
		riverHigh1: wp("rios", "altaMax", 40), // Height above the waterline where rivers are gone (highlands stay dry)
		riverDrop: wp("rios", "cauce", 3), // Rivers cut down to seaLevel - this, so the water floods them
		riverMaxCut: wp("rios", "corteMax", 52), // Carve depth cap: how high a river may still cut down to the waterline. The bed NEVER goes below seaLevel-riverDrop (floorR clamps), so deep caps only extend connectivity through peaks; flanks stay smooth (maxDelta<=2)
		riverFloodBoost: wp("rios", "floodBoost", 1.0), // Flood guarantee multiplier on shape.river: 1.0 = classic cut. >1 floods noise dips but doubles bank slopes (3-block steps) - keep at 1
	}
	win.biomeSettings = biomeSettings
	// Pristine defaults: creating a new world always uses the CURRENT
	// generator settings, never leftovers from a previously loaded world
	const defaultRiverSettings = Object.assign({}, riverSettings)
	const defaultBiomeSettings = Object.assign({}, biomeSettings)
	const defaultGeneratorSettings = Object.assign({}, generator)
	function restoreDefaultSettings() {
		Object.assign(riverSettings, defaultRiverSettings)
		Object.assign(biomeSettings, defaultBiomeSettings)
		Object.assign(generator, defaultGeneratorSettings)
	}
	let erosionNoise = null
	let temperatureNoise = null
	let humidityNoise = null

	// Climate at a column, normalized to [0, 1] with contrast expansion.
	// Pure organic noise: no coordinate warping. The humidity channel
	// runs at its own broader scale (humidityScale) and subtropical
	// drying couples it to temperature (heat suppresses humidity), so
	// desert and forest zones rarely overlap and stay coherent.
	function climateAt(x, z) {
		if (!erosionNoise || !temperatureNoise || !humidityNoise) {
			return null
		}
		let s = biomeSettings.climateScale
		let e = erosionNoise.noise2d(x * s, z * s)
		let t = temperatureNoise.noise2d(x * s, z * s)
		let hs = s * biomeSettings.humidityScale
		let h = humidityNoise.noise2d(x * hs, z * hs)
		let spread = biomeSettings.climateSpread
		let expand = function(v) {
			return Math.max(0, Math.min(1, (v - 0.5) / (2 * spread) + 0.5))
		}
		let temp = expand(t * 0.5 + 0.5)
		let humidity = expand(h * 0.5 + 0.5)
		humidity = Math.max(0, humidity - biomeSettings.desertDryness * Math.max(0, temp - biomeSettings.desertTemp))
		return {
			erosion: expand(e * 0.5 + 0.5),
			temp: temp,
			humidity: humidity
		}
	}

	// Smooth terrain noise: the base swell (100-block waves) dominates;
	// roughness damps the two detail octaves and the grainy 12.5-block
	// octave of the original stack is removed entirely. 0 = pure clean
	// waves, 1 = close to the original 4-octave feel. Returns null when
	// the generator is not seeded yet.
	function smoothTerrain(x, z) {
		let g = noiseProfile.generator
		if (!g) {
			return null
		}
		let f = generator.smooth
		let r = biomeSettings.terrainRoughness
		let n = (1 + g.noise2d(x * f, z * f)) / 2
		n += r * 0.5 * (1 + g.noise2d(x * 2 * f, z * 2 * f)) / 2
		n += r * 0.25 * (1 + g.noise2d(x * 4 * f, z * 4 * f)) / 2
		return n / (1 + 0.75 * r)
	}

	// ==================================================================
	// TERRAIN SHAPE FIELD
	// Shape layer ported from the upstream world_new.js generator and
	// blended UNDER the erosion-driven datum relief, so the tuned
	// biome / lake / border-river system keeps working on top of it:
	//   - seeded 2D simplex layers
	//   - DOMAIN WARPING: coastlines and ranges get twisted, so nothing
	//     reads as a circle or a blob
	//   - CONTINENTALNESS -> piecewise curve: real oceans, shelves,
	//     inland plains and plateaus instead of one uniform swell
	//   - RIDGED NOISE: rounded crests over a broad massif, still gated
	//     by erosion so /locate mountains keeps telling the truth
	//   - RIVER NETWORK: the zero line of a noise field carved down to
	//     the waterline, fading out in the highlands
	// Every value is exposed through biome-params.js.
	// ==================================================================

	function mixSeed(seed, n) {
		let h = seed + Math.imul(n, 0x9E3779B1) | 0
		h = Math.imul(h ^ h >>> 16, 0x85EBCA6B)
		h = Math.imul(h ^ h >>> 13, 0xC2B2AE35)
		return h ^ h >>> 16
	}

	// 2D simplex noise, 8 evenly spread gradient directions (~ -1 to 1)
	function makeSimplex2D(seed) {
		let perm = new Uint8Array(512)
		let src = new Uint8Array(256)
		for (let i = 0; i < 256; i++) {
			src[i] = i
		}
		let state = seed | 0
		for (let i = 255; i > 0; i--) {
			state = state + 0x6D2B79F5 | 0
			let t = Math.imul(state ^ state >>> 15, 1 | state)
			t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t
			let j = ((t ^ t >>> 14) >>> 0) % (i + 1)
			let tmp = src[i]
			src[i] = src[j]
			src[j] = tmp
		}
		for (let i = 0; i < 512; i++) {
			perm[i] = src[i & 255]
		}
		let R = Math.SQRT1_2
		let gx = [ 1, -1, 0, 0, R, -R, R, -R ]
		let gz = [ 0, 0, 1, -1, R, R, -R, R ]
		let F2 = 0.5 * (Math.sqrt(3) - 1)
		let G2 = (3 - Math.sqrt(3)) / 6
		return function(x, z) {
			let skew = (x + z) * F2
			let i = Math.floor(x + skew)
			let j = Math.floor(z + skew)
			let unskew = (i + j) * G2
			let x0 = x - (i - unskew)
			let z0 = z - (j - unskew)
			let i1 = x0 > z0 ? 1 : 0
			let j1 = 1 - i1
			let x1 = x0 - i1 + G2
			let z1 = z0 - j1 + G2
			let x2 = x0 - 1 + 2 * G2
			let z2 = z0 - 1 + 2 * G2
			let ii = i & 255
			let jj = j & 255
			let n = 0
			let a = 0.5 - x0 * x0 - z0 * z0
			if (a > 0) {
				let g = perm[ii + perm[jj]] & 7
				a *= a
				n += a * a * (gx[g] * x0 + gz[g] * z0)
			}
			a = 0.5 - x1 * x1 - z1 * z1
			if (a > 0) {
				let g = perm[ii + i1 + perm[jj + j1]] & 7
				a *= a
				n += a * a * (gx[g] * x1 + gz[g] * z1)
			}
			a = 0.5 - x2 * x2 - z2 * z2
			if (a > 0) {
				let g = perm[ii + 1 + perm[jj + 1]] & 7
				a *= a
				n += a * a * (gx[g] * x2 + gz[g] * z2)
			}
			return 70 * n
		}
	}

	// Fractal sum, normalized so the result stays within about -1 to 1
	function fbm(fn, x, z, octaves) {
		let amp = 1, freq = 1, sum = 0, norm = 0
		for (let o = 0; o < octaves; o++) {
			sum += fn(x * freq, z * freq) * amp
			norm += amp
			amp *= 0.5
			freq *= 2.03
		}
		return sum / norm
	}

	function clamp01V(v) {
		return v < 0 ? 0 : v > 1 ? 1 : v
	}

	function smoothstepV(a, b, x) {
		let t = clamp01V((x - a) / (b - a))
		return t * t * (3 - 2 * t)
	}

	// Piecewise linear curve lookup, clamped at both ends
	function curveAt(points, v) {
		if (v <= points[0][0]) {
			return points[0][1]
		}
		for (let i = 1; i < points.length; i++) {
			if (v <= points[i][0]) {
				let a = points[i - 1], b = points[i]
				return a[1] + (b[1] - a[1]) * (v - a[0]) / (b[0] - a[0])
			}
		}
		return points[points.length - 1][1]
	}

	// The simplex layers, rebuilt whenever the world seed is set
	let TN = null

	function initTerrainNoise(seed) {
		TN = {}
		let n = 0
		for (let name of [ "warpX", "warpZ", "continent", "rough", "ridge", "river" ]) {
			TN[name] = makeSimplex2D(mixSeed(seed, ++n))
		}
		shapeMemo = null
	}

	// The expensive shape field, evaluated once per column and shared by
	// terrainHeight and every rawColumnGen branch through this 1-entry
	// memo (call it with the same coordinates to get the cache).
	let shapeMemo = null

	function shapeFieldAt(x, z) {
		if (shapeMemo && shapeMemo.x === x && shapeMemo.z === z) {
			return shapeMemo
		}
		let out = { x: x, z: z, wx: x, wz: z, cont: 0, cval: 0, ridge: 0, river: 0, riverWater: false }
		if (TN) {
			// Domain warping: the whole relief is read through twisted
			// coordinates, which is what kills the circular/blobby look.
			let ws = biomeSettings.warpScale
			let wn = biomeSettings.warpStrength
			let wx = x + TN.warpX(x * ws, z * ws) * wn
			let wz = z + TN.warpZ(x * ws, z * ws) * wn
			out.wx = wx
			out.wz = wz
			// Continentalness: one low frequency channel that decides where
			// the oceans, the shelves and the inland plateaus are.
			let cs = biomeSettings.continentScale
			let cval = fbm(TN.continent, wx * cs, wz * cs, 4) * biomeSettings.continentGain + biomeSettings.continentBias
			cval = cval < -1 ? -1 : cval > 1 ? 1 : cval
			out.cval = cval
			out.cont = curveAt(biomeSettings.continentCurve, cval)
			// Flat plains vs rough country.
			let rs = biomeSettings.roughScale
			let rough = smoothstepV(biomeSettings.roughLo, biomeSettings.roughHi, fbm(TN.rough, wx * rs, wz * rs, 3))
			// SOFT PEAKS, no crest lines: the mountain field is the
			// POSITIVE half of a smooth fbm shaped into a dome. Peaks
			// sit on the noise's isolated maxima (slope zero at the
			// top, rounded) instead of along a zero-contour line, so
			// ranges read as clusters of soft domes. agudeza widens
			// the lifted area; the highest values flatten into gentle
			// highland plateaus, never ridges.
			let gs = biomeSettings.ridgeScale
			let rn = fbm(TN.ridge, wx * gs, wz * gs, 2)
			let bump = clamp01V(rn * biomeSettings.ridgeSharp)
			let ridge = bump * bump * (3 - 2 * bump)
			let c = climateAt(x, z)
			// Erosion gate: mountains are ONLY genuinely low-erosion
			// country, fading to nothing by ridgeErosionHi — the same
			// story /locate mountains tells.
			let lowErosion = c ? 1 - smoothstepV(biomeSettings.ridgeErosionHi, biomeSettings.ridgeErosionLo, c.erosion) : 1
			let mask = smoothstepV(biomeSettings.ridgeMaskC0, biomeSettings.ridgeMaskC1, cval)
				* smoothstepV(biomeSettings.ridgeRough0, biomeSettings.ridgeRough1, rough)
				* lowErosion
				* (c ? 1 - smoothstepV(biomeSettings.desertTemp - 0.04, biomeSettings.desertTemp + 0.01, c.temp) : 1)
			out.ridge = mask * (biomeSettings.ridgeBase + ridge * biomeSettings.mountainHeight)
// River network: the zero line of a noise field, cut down to
		// the waterline. Rivers only ever cut, never raise.
		// Fewer octaves (2) → smoother zero contour → longer runs
		let vs = biomeSettings.riverNetworkScale
		let rv = Math.abs(fbm(TN.river, wx * vs, wz * vs, 2))
			let rm = (1 - smoothstepV(biomeSettings.riverNetworkCore, biomeSettings.riverNetworkWidth, rv))
				* (1 - smoothstepV(riverSettings.seaLevel + biomeSettings.riverHigh0, riverSettings.seaLevel + biomeSettings.riverHigh1, out.cont + biomeSettings.plainsBase))
			out.river = rm
			if (rm > 0) {
				let floorR = riverSettings.seaLevel - biomeSettings.riverDrop
				out.riverWater = out.cont + biomeSettings.plainsBase > floorR
			}
		}
		shapeMemo = out
		return out
	}

	// Single source of truth for terrain height, now composed in layers:
	//   datum (erosion blend) + continent offset + eroded relief
	//   + ridged crests - river network
	// Erosion still blends ONLY the amplitude and base height
	// continuously (constant frequency), so the smooth wave shapes are
	// preserved everywhere: biome transitions never cliff. The swell
	// value is cubed (most ground stays within a couple blocks of the
	// datum; only the swell peaks lift into hills) and the amplitude
	// curve is cubic (real mountains only where erosion is genuinely
	// low). The continent offset and the ridges are read through the
	// domain-warped coordinates, so coastlines and ranges never look
	// circular. Falls back to the classic formula before the world
	// seeds.
	function terrainHeight(x, z) {
		let shape = shapeFieldAt(x, z)
		let c = climateAt(x, z)
		let amp = generator.height
		let base = generator.extra
		if (c) {
			let m = 1 - c.erosion
			// GROUND DATUM AT THE WATERLINE: the base IS the sea level —
			// the general terrain sits right at the water, and everything
			// else (hills, mountains) RISES from it. The swell value is
			// cubed (most ground stays within a couple blocks of the
			// datum; only the swell peaks lift into hills) and the
			// amplitude curve is cubic (real mountains only where
			// erosion is genuinely low).
			amp = biomeSettings.plainsAmp + (biomeSettings.mountainAmp - biomeSettings.plainsAmp) * m * m * m
			base = biomeSettings.plainsBase + (biomeSettings.mountainBase - biomeSettings.plainsBase) * m
		}
		// Continentalness: oceans, shelves and inland plateaus, expressed
		// as an offset from the datum.
		base += shape.cont
		let value = smoothTerrain(shape.wx, shape.wz)
		if (value === null) {
			value = noise(x * generator.smooth, z * generator.smooth)
		}
		let h = base + amp * value * value * value + shape.ridge
		// River network: cut down toward the waterline, never raise.
		// The cut is CAPPED (riverMaxCut): a river crossing high
		// country opens a gentle gorge of bounded depth instead of a
		// vertical slit, and only genuinely low valleys flood.
		if (shape.river > 0) {
			let floorR = riverSettings.seaLevel - biomeSettings.riverDrop
			h -= Math.min(Math.max(0, h - floorR), biomeSettings.riverMaxCut) * Math.min(1, shape.river * biomeSettings.riverFloodBoost)
		}
		let top = maxHeight - 8
		// Single rounding: biome bases are fractional (continuous blend),
		// so the FULL height must be rounded here. Downstream code (genChunk,
		// tops, setBlock indices) requires integers.
		if (h < 4) {
			return 4
		}
		if (h > top) {
			return top
		}
		return Math.round(h)
	}

	// Relief-adjusted climate: THE single source of truth shared by
	// biomeAt and the border-river field, so the river hugs the exact
	// biome border. The relief only bends the climate NEAR the frontier
	// (tapered by value distance to the threshold): borders follow the
	// relief's height contours, while zone interiors stay homogeneous
	// (no relief-carved holes inside a biome).
	function climateEffAt(x, z) {
		let c = climateAt(x, z)
		if (!c) {
			return null
		}
		let relief = (terrainHeight(x, z) - riverSettings.seaLevel) / 50
		let e = biomeSettings.biomeReliefEffect
		let band = biomeSettings.reliefBand
		let pt = Math.max(0, 1 - Math.abs(c.temp - biomeSettings.desertTemp) / band)
		let ph = Math.max(0, 1 - Math.abs(c.humidity - biomeSettings.forestHumidity) / band)
		return {
			temp: c.temp - relief * e * pt,
			hum: c.humidity - relief * e * 0.5 * ph,
			erosion: c.erosion
		}
	}

	// Visual biome at a column: surface blocks and tree density only.
	function biomeAt(x, z) {
		// Isla del menu: plains SIEMPRE.  El mundo del menu se siembra con
		// un worldSeed aleatorio y su clima podria tocar desierto (genChunk
		// le pondria arena a toda la isla) o pantano (tinte oscuro).
		if (menuIsla) {
			return "plains"
		}
		let c = climateEffAt(x, z)
		if (!c) {
			return "plains"
		}
		if (c.temp >= biomeSettings.desertTemp) {
			return "desert"
		}
		// SWAMP: humid flat lowlands (high erosion = low, smooth ground) —
		// the wetland biome, full of shallow ponds.
		if (c.hum >= biomeSettings.swampHumidity && c.erosion >= biomeSettings.swampFlatness) {
			return "swamp"
		}
		if (c.hum >= biomeSettings.forestHumidity) {
			return "forest"
		}
		return "plains"
	}

	// World-space distance (in blocks) to the nearest biome frontier:
	// the relief-adjusted threshold contours. Normalized by the local
	// field gradient (finite differences) so the border river keeps a
	// constant block width instead of swelling with flat gradients.
	// Cheap reject: beyond 0.45 in value space on BOTH channels not
	// even the flattest gradient can put a frontier within valley
	// reach (~120 blocks).
	function borderDistanceAt(x, z) {
		let c0 = climateEffAt(x, z)
		if (!c0) {
			return Infinity
		}
		let dvH = Math.abs(c0.hum - biomeSettings.forestHumidity)
		let dvT = Math.abs(c0.temp - biomeSettings.desertTemp)
		if (Math.min(dvH, dvT) > 0.45) {
			return Infinity
		}
		let d = 48
		let cx = climateEffAt(x + d, z)
		let cz = climateEffAt(x, z + d)
		if (!cx || !cz) {
			return Infinity
		}
		let dist = Infinity
		let gx = (cx.hum - c0.hum) / d
		let gz = (cz.hum - c0.hum) / d
		let g = Math.sqrt(gx * gx + gz * gz)
		dist = Math.min(dist, dvH / Math.max(g, 0.0002))
		gx = (cx.temp - c0.temp) / d
		gz = (cz.temp - c0.temp) / d
		g = Math.sqrt(gx * gx + gz * gz)
		dist = Math.min(dist, dvT / Math.max(g, 0.0002))
		return dist
	}

	// Tree density for the biome at a column
	function treeChanceAt(x, z) {
		// Isla del menu: plains da 0.002 (3 arboles en toda la isla).
		// 0.012 sobre ~1300 columnas de cesped deja unos 15 arboles.
		if (menuIsla) {
			return 0.012
		}
		let biome = biomeAt(x, z)
		if (biome === "desert") {
			return biomeSettings.desertTreeChance
		}
		if (biome === "forest") {
			return biomeSettings.forestTreeChance
		}
		if (biome === "swamp") {
			return biomeSettings.swampTreeChance
		}
		return biomeSettings.plainsTreeChance
	}

	// Especie de arbol de una columna y bloques con que se construye.
	// La FORMA la genera TreeGen (png/trees/tree_gen.js, extraido del
	// visor png/trees/generador arboles.html); aqui solo se elige la
	// especie por bioma.  Bosque: 60% roble / 40% abedul (las mismas
	// proporciones del arbol viejo), pantano: sauce de ramas caidas,
	// llanura (y la isla del menu): roble.  El dado de especie es
	// hash por columna, no el random() del chunk: no depende de
	// cuantos arboles hayan salido antes en el chunk.
	const ARBOL_BLOQUES = {
		roble: { log: "oakLog", leaf: "leaves" },
		abedul: { log: "birchLog", leaf: "birchLeaves" },
		sauce: { log: "darkOakLog", leaf: "swampLeaves" },
	}
	function treeSpeciesAt(x, z) {
		let biome = biomeAt(x, z)
		if (biome === "swamp") {
			return "sauce"
		}
		if (biome === "forest" && hash(x * 3 + 1, z * 3 + 2) > 0.2) {
			return "abedul"
		}
		return "roble"
	}

	// Surface-plant density for the biome at a column. Dense grass on
	// plains and forests, sparse in the swamp (its clear tint shows up
	// thin in the wetland). Missing override or unknown biome -> the
	// global weedDensity, so worlds saved without the per-biome map
	// keep their old behaviour.
	function weedDensityAt(x, z) {
		let byBiome = biomeSettings.weedDensityByBiome
		let v = byBiome ? byBiome[biomeAt(x, z)] : undefined
		return v === undefined ? biomeSettings.weedDensity : v
	}

	// Isla del menu principal: columna pura, sin ruido sembrado, para que
	// se vea igual en todas las sesiones.  Devuelve la MISMA forma que
	// rawColumnGen, de modo que genChunk pone cesped/arena/agua y tops[]
	// sin tocar nada mas.  Los gen SIEMPRE enteros (terrainHeight deja
	// escrito que tops/setBlock los exigen).
	//
	// Perfil en dos tramos (medido desde la orilla hacia dentro: s):
	//   s < 0        fondo marino plano (seaShelfDepth bajo el mar)
	//   0..orilla    rampa corta 59 -> playaTop.  Con la banda de arena
	//                (playas.ancho = 4 sobre el nivel del mar) eso deja
	//                ~3 anillos de agua poco profunda y ~3 de arena;
	//                el resto de la isla es solo cesped.
	//   > orilla     cuerpo suave: sube despacio hasta seaLevel + altura,
	//                con un ola fina para que no salga una mesa plana.
	function islaColumn(wx, wz) {
		let dx = wx - ISLA.x
		let dz = wz - ISLA.z
		// Contorno irregular (tres senos: costa con bahias y peninsulas)
		let d = Math.sqrt(dx * dx + dz * dz)
			+ 3 * Math.sin(wx * 0.23) * Math.cos(wz * 0.19)
			+ 1.5 * Math.sin((wx + wz) * 0.41)
		let s = ISLA.radio - d
		let nivel = riverSettings.seaLevel
		let fondo = nivel - riverSettings.seaShelfDepth
		let playaTop = nivel + Math.max(1, biomeSettings.beachWidth)
		let cima = nivel + ISLA.altura
		let gen
		if (s <= 0) {
			gen = fondo
		} else if (s < ISLA.orilla) {
			gen = Math.round(fondo + (s / ISLA.orilla) * (playaTop - fondo))
		} else {
			let u = Math.min(1, (s - ISLA.orilla) / (ISLA.radio - ISLA.orilla))
			gen = Math.round(playaTop + u * (cima - playaTop)
				+ 1.2 * Math.sin(wx * 0.09) * Math.cos(wz * 0.11))
		}
		if (gen < nivel) {
			// lake solo bajo el agua: la fila contigua tiene agua al lado
			// (nearLake en genChunk) y recibe el anillo de arena de la orilla.
			return { gen: gen, water: true, river: false, lake: true, dw: Infinity }
		}
		return { gen: gen, water: false, river: false, lake: false, dw: Infinity }
	}

	// Pure per-column terrain computation: everything that determines the
	// height, water state and beach zone of a column BEFORE any slope
	// limiting. Being a pure function of world coordinates, adjacent chunks
	// always compute border values identically (seam-free by construction).
	function rawColumnGen(wx, wz) {
		// Menu principal: la isla en vivo.  Un solo gancho; genChunk,
		// populate y el relleno de agua funcionan sin mas cambios.
		if (menuIsla) {
			return islaColumn(wx, wz)
		}
		// Evaluated FIRST so the 1-entry memo serves terrainHeight below.
		let shape = shapeFieldAt(wx, wz)
		let gen = superflat ? 4 : terrainHeight(wx, wz)
		let water = false
		let riverWater = false
		let lakeWater = false
		let dw = Infinity
		if (!superflat && riverNoise && lakeNoise) {
			// Frontier distance first: inside the river valleys the smooth
			// dw contour IS the coast shape — the waterline wobble is
			// disabled there (delicate, spike-free river edges).
			let dw = borderDistanceAt(wx, wz)
			// ORGANIC MEANDER: the channel weaves smoothly around the
			// frontier contour (a single soft octave, no coordinate
			// warping — the biome border itself stays pure). Everything
			// downstream (valley profile, bed, wading rim, sand mask)
			// follows the meandering course.
			if (dw < 180) {
				dw -= riverNoise.noise2d(wx * 0.005 + 3700, wz * 0.005 - 3700) * 11
			}
			// Irregular coasts: high-frequency height wobble, ONLY at
			// the waterline (coastBand), carving inlets and peninsulas.
			// Plains sit well above this band: they stay untouched.
			let coastAmp = Math.max(0, 1 - Math.abs(gen - riverSettings.seaLevel) / riverSettings.coastBand)
			if (coastAmp > 0 && dw > 60) {
				gen = Math.round(gen + (riverNoise.noise2d(wx * riverSettings.coastScale, wz * riverSettings.coastScale) - 0.5) * 2 * riverSettings.coastWobble * coastAmp)
			}
			// SWAMP TERRAIN: the wetland biome flattens and lowers its OWN
			// ground toward the waterline — broad shallow flats where ponds
			// collect. The strength tapers in with humidity, so the biome
			// edge blends smoothly (no cliffs at the frontier).
			let bB = biomeAt(wx, wz)
			if (bB === "swamp" && gen > riverSettings.seaLevel) {
				let cB = climateEffAt(wx, wz)
				let swampT = Math.min(1, (cB.hum - biomeSettings.swampHumidity) / biomeSettings.swampFlattenRamp)
				if (swampT > 0) {
					gen = Math.floor(riverSettings.seaLevel + (gen - riverSettings.seaLevel) * (1 - swampT * (1 - biomeSettings.swampFlat)))
				}
			}
			// INTERIOR LAKES: TERRAIN GENERATION, never a cut. The lake field
			// selects zones; only where the terrain ALREADY sits low does the
			// generator form a wide gentle hollow whose floor reaches just
			// below the waterline (shallow ponds, water floods everything
			// under the sea level naturally). Hills and high ground are never
			// touched — that is forbidden. Ponds are far more frequent in
			// swamps, then forests (biome boost on the influence).
			let lval = lakeNoise.noise2d(wx * riverSettings.lakeScale, wz * riverSettings.lakeScale)
			// Biome boost scales the noise VALUE before the threshold: wetter
			// biomes get a lower effective threshold — genuinely more ponds.
			let dvL = lval
			if (bB === "swamp") {
				dvL *= riverSettings.swampLakeBoost
			} else if (bB === "forest") {
				dvL *= riverSettings.forestLakeBoost
			}
			dvL -= riverSettings.lakeThreshold
			if (dvL > 0 && gen > riverSettings.seaLevel) {
				// Gate referenced to the LOCAL ground level (the datum plus the
				// continent offset): lakes only form where the swell dips
				// below the surrounding land — hondonadas. Flat plateaus
				// and mountains never qualify, so giant lakes are impossible
				// and the ponds follow the terrain instead of one altitude.
				// GATE GENTLENESS: the height fade runs LINEARLY over
				// lakeHeightBand blocks: ZERO at datum+band (the design
				// line "hills never touched") and FULL at datum itself,
				// where the hondonadas live. The old gate compressed the
				// same drop into 1.5 blocks (/0.3) plus binary dw/rivers
				// steps — a slope gain of (gen-lakeFloor)/1.5 ≈ 14x that
				// drew 14-15 block walls around every hollow rim. The
				// gain now is (gen-lakeFloor)/band ≈ 5x at the rim.
				let datum = biomeSettings.plainsBase + shape.cont
				let hFade = (datum + riverSettings.lakeHeightBand - gen) / riverSettings.lakeHeightBand
				hFade = Math.max(0, Math.min(1, hFade))
				// No lakes inside the frontier river's valley: the border
				// river stays untouched — lakes never merge with it. The
				// same applies to the natural river network, so ponds
				// never flood a river bed. (Smooth, not a step.)
				hFade *= smoothstepV(50, 70, dw)
				hFade *= 1 - smoothstepV(0.2, 0.5, shape.river)
				let climate = climateAt(wx, wz)
				if (climate && climate.temp > biomeSettings.desertTemp - riverSettings.lakeDesertFade) {
					hFade *= Math.max(0, 1 - (climate.temp - (biomeSettings.desertTemp - riverSettings.lakeDesertFade)) / riverSettings.lakeDesertFade)
				}
				if (hFade > 0) {
					// Smooth hollow: the shore is the bowl's natural slope —
					// no carved rings, the coast shelf finishes the waterline.
					let tLraw = Math.min(1, dvL / riverSettings.lakeEdge)
					let tL = tLraw * tLraw * (3 - 2 * tLraw) * hFade
					let targetL = Math.min(gen, riverSettings.seaLevel - 1 - riverSettings.lakeDepth)
					gen = Math.floor(gen + (targetL - gen) * tL)
					if (gen < riverSettings.seaLevel) {
						lakeWater = true
					}
				}
			}
			// BORDER RIVER VALLEY: the biome frontier IS the river, and
			// the river SHAPES the terrain around it: every frontier
			// organizes the land into a valley that descends to the
			// water from both sides. The valley half-width grows with
			// the surrounding height (capped slope). The profile is a
			// SINGLE smoothstep height-quantized: the rise is evenly
			// spread across the whole valley, every step is exactly one
			// block, and the step lines are pure contours of the smooth
			// relief field — fluid, simple, never brusque. Underwater
			// terrain is never touched (estuaries merge with the sea
			// naturally).
			if (dw < 120 && gen > riverSettings.seaLevel) {
				let height = gen - riverSettings.seaLevel
				let vw = Math.min(biomeSettings.borderValleyMax, biomeSettings.borderValleyMin + height / biomeSettings.borderValleySlope)
				let f = dw / vw
				if (f < 0) {
					f = 0
				}
				if (f < 1) {
					// ORGANIC VALLEY RELIEF: inside the valley the terrain
					// follows only the smooth base swell — the small-scale
					// roughness chatter is faded out and only returns over
					// the outer quarter of the valley, so the
					// coast-to-biome strip reads as clean organic arcs and
					// the junction never steps nor shows a noisy band.
					let cV = climateAt(wx, wz)
					let mV = cV ? 1 - cV.erosion : 0
					let ampV = biomeSettings.plainsAmp + (biomeSettings.mountainAmp - biomeSettings.plainsAmp) * mV * mV * mV
					let baseV = biomeSettings.plainsBase + (biomeSettings.mountainBase - biomeSettings.plainsBase) * mV + shape.cont
					let v0 = (1 + noiseProfile.generator.noise2d(shape.wx * generator.smooth, shape.wz * generator.smooth)) / 2
					// hS must mirror terrainHeight INCLUDING the natural
					// river carve — otherwise the valley rebuilds UNCUT
					// ground next to carved terrain and the mixF blend
					// draws a tall wall parallel to the frontier river.
					let hSraw = baseV + ampV * v0 * v0 * v0
					if (shape.river > 0) {
						let floorSr = riverSettings.seaLevel - biomeSettings.riverDrop
						hSraw -= Math.min(Math.max(0, hSraw - floorSr), biomeSettings.riverMaxCut) * Math.min(1, shape.river * biomeSettings.riverFloodBoost)
					}
					let hS = Math.round(hSraw) - riverSettings.seaLevel
					if (hS < 0) {
						hS = 0
					}
					let tR = Math.max(0, Math.min(1, (f - 0.75) / 0.25))
					let mixF = tR * tR * (3 - 2 * tR)
					let hEff = hS + (height - hS) * mixF
					// UNIFORM ONE-BLOCK STAIRCASE: single smoothstep,
					// floored by height — each step is exactly one block
					// tall and the step lines are smooth contours of the
					// hEff field.
					let ss = f * f * (3 - 2 * f)
					gen = riverSettings.seaLevel + Math.floor(hEff * ss)
				}
				// Constant channel width: the edge is exactly the meander
				// curve — no width jitter of any kind.
				let hw = biomeSettings.borderRiverWidth * 0.5
				if (dw < hw) {
					// Terraced bed: flat plateaus with 1-block steps, the same
					// staircase language as the terrain relief
					let dd = 1 - dw / hw
					let step = Math.floor(dd * riverSettings.riverTerraces) / riverSettings.riverTerraces + 1 / riverSettings.riverTerraces
					let depth = Math.round(step * riverSettings.maxDepth)
					let floor = riverSettings.seaLevel - 1 - depth
					if (floor < gen) {
						gen = floor
					}
					water = true
					riverWater = true
				} else if (dw < hw * 1.35) {
					// Wading rim: a uniform 1-deep water shelf hugging the
					// channel — the visible waterline is one clean row and
					// the shore band sits directly on real water (sand can
					// only ever be attached to actual water).
					if (gen > riverSettings.seaLevel - 1) {
						gen = riverSettings.seaLevel - 1
					}
					water = true
				}
			}
			// Coast shelf AFTER the carves: rivers and lakes crossing
			// low ground inherit the gradual sea-coast profile. Floored
			// to whole blocks: every shore comes up as clean geometric
			// terraces — flat plateaus with 1-block steps, no noise mush.
			if (gen > riverSettings.seaLevel && gen < riverSettings.seaLevel + riverSettings.coastShelf) {
				let h = gen - riverSettings.seaLevel
				let f = riverSettings.coastFlatness
				gen = Math.floor(riverSettings.seaLevel + h * (f + (1 - f) * h / riverSettings.coastShelf))
			}
			// Sand band: extra compression near the waterline that eases to
			// full slope at the band edge, so the dirt-to-sand transition is
			// always 1 block (no step at the boundary). Applies to sea,
			// lake and border-river shores alike.
			if (biomeSettings.beach && gen >= riverSettings.seaLevel && gen < riverSettings.seaLevel + biomeSettings.beachWidth) {
				let h = gen - riverSettings.seaLevel
				let f = biomeSettings.beachFlatness
				let w = Math.max(1, biomeSettings.beachWidth)
				gen = Math.floor(riverSettings.seaLevel + h * (f + (1 - f) * h / w))
			}
			// Seas and lakes: valleys below sea level flood naturally
			// (much deeper than rivers)
			if (gen < riverSettings.seaLevel) {
				water = true
			}
		}
		return { gen: gen, water: water, river: riverWater, lake: lakeWater, dw: dw }
	}
	let maxHeight = 255
	let blockOutlines = false
	let blockFill = true
	let updateHUD = true
	// Entidad a la que se apunto en el frame anterior (ver drawScreens.play)
	let heartsMobPrev = null
	const CUBE     = 0
	const SLAB     = 0x100 // 9th bit
	const STAIR    = 0x200 // 10th bit
	const FLIP     = 0x400 // 11th bit
	const NORTH    = 0 // 12th and 13th bits for the 4 directions
	const SOUTH    = 0x800
	const EAST     = 0x1000
	const WEST     = 0x1800
	const ROTATION = 0x1800 // Mask for the direction bits
	let blockMode  = CUBE
	let tex
	let textureMap
	let variantTiles
	let dirtBuffer
	let dirtTexture
	let textureCoords
	let texCoordsBuffers
	let mainbg, dirtbg // Background images
	// Scratch buffer for one chunk's mesh. Out-of-range writes are dropped
	// silently, so it has to hold the worst chunk: crossed plants add up to
	// ~16 quads per surface column, and the leaf bush adds up to 10 fringe
	// quads per fully visible leaf block (6 cube faces + 4 radial planes
	// + techo, todos x2 windings) on top of the terrain itself.
	let bigArray = win.bigArray && win.bigArray.length >= 1200000 ? win.bigArray : new Float32Array(1200000)
	win.bigArray = bigArray

	// Callback functions for all the screens; will define them further down the page
	let drawScreens = {
		"main menu": () => {},
		"options": () => {},
		"play": () => {},
		"pause": () => {},
		"creation menu": () => {},
		"inventory": () => {},
		"book": () => {},
		"multiplayer menu": () => {},
		"comingsoon menu": () => {},
		"loadsave menu": () => {},
	}
	// Escena del libro (escribir/firmar): las zonas de escritura son HTML
	// sobre el canvas (mismo patron que chatbox).
	// Zonas de escritura del libro (kit assets_books): portada
	// (titulo sobre la etiqueta de la tapa) y las dos hojas.  Los ids van
	// sin guiones porque los leemos con getElementById.
	const bookcover = document.getElementById("bookcover")
	const bookpageL = document.getElementById("bookpageL")
	const bookpageR = document.getElementById("bookpageR")
	const bookchapter = document.getElementById("bookchapter")
	const bookInputs = [bookcover, bookpageL, bookpageR]
	let html = {
		pause: {
			enter: [window.message],
			exit: [window.savebox, window.saveDirections, window.message]
		},
		book: {
			// Solo callbacks: onenter abre en la portada y sincroniza los
			// inputs con el slot; onexit hace flush del texto y esconde
			// todo (incluido el mini-input de nombre de capitulo).
			// onexit de la escena vieja corre ANTES de que screen cambie
			// (changeScene), y el value de los inputs se lee oculto.
			onenter: () => {
				bookView = "cover"
				bookSpread = 0
				syncBookInputs()
				for (const el of bookInputs) {
					el.classList.remove("hidden")
				}
				bookcover.focus()
			},
			onexit: () => {
				flushBookAll()
				bookChapterEdit = -1
				if (bookchapter) {
					bookchapter.classList.add("hidden")
					bookchapter.blur()
				}
				for (const el of bookInputs) {
					el.classList.add("hidden")
					el.blur()
				}
				bookSlot = null
			}
		},
		"loadsave menu": {
			enter: [window.worlds, window.boxCenterTop, window.quota],
			exit: [window.worlds, window.boxCenterTop, window.quota],
			onenter: () => {
				window.boxCenterTop.placeholder = "Enter Save String (Optional)"
				if (navigator && navigator.storage && navigator.storage.estimate) {
					navigator.storage.estimate().then(data => {
						window.quota.innerText = `${data.usage.toLocaleString()} / ${data.quota.toLocaleString()} bytes (${(100 * data.usage / data.quota).toLocaleString(undefined, { maximumSignificantDigits: 2 })}%) of your quota used`
					}).catch(console.error)
				}
				window.boxCenterTop.onmousedown = e => {
					let elem = document.getElementsByClassName("selected")
					if (elem && elem[0]) {
						elem[0].classList.remove("selected")
					}
					selectedWorld = 0
					Button.draw()
				}
			},
			onexit: () => {
				window.boxCenterTop.onmousedown = null
			}
		},
		"creation menu": {
			enter: [window.boxCenterTop],
			exit: [window.boxCenterTop],
			onenter: () => {
				window.boxCenterTop.placeholder = "Enter World Name"
				window.boxCenterTop.value = ""
			}
		},
		loading: {
			onenter: startLoad
		},
		editworld: {
			enter: [window.boxCenterTop],
			exit: [window.boxCenterTop],
			onenter: () => {
				window.boxCenterTop.placeholder = "Enter World Name"
				window.boxCenterTop.value = ""
			}
		}
	}

	let screen = "main menu"
	win.screen = screen
	let previousScreen = screen
	function changeScene(newScene) {
		if (screen === "options") {
			// Espejo sincrono (mismo contenido que la DB) para que el proximo
			// arranque aplique los ajustes antes del primer frame.
			try {
				win.localStorage.setItem("voxeland.settings", JSON.stringify(settings))
			} catch (e) {
				console.error(e)
			}
			saveToDB("settings", settings).catch(e => console.error(e))
		}

		if (html[screen] && html[screen].exit) {
			for (let element of html[screen].exit) {
				element.classList.add("hidden")
			}
		}

		if (html[newScene] && html[newScene].enter) {
			for (let element of html[newScene].enter) {
				element.classList.remove("hidden")
			}
		}

		if (html[newScene] && html[newScene].onenter) {
			html[newScene].onenter()
		}
		if (html[screen] && html[screen].onexit) {
			html[screen].onexit()
		}

		previousScreen = screen
		screen = newScene
		win.screen = screen
		// El menu principal pinta la isla en vivo a partir de ahora.
		if (newScene === "main menu") {
			activarMenuIsla()
		}
		mouseDown = false
		drawScreens[screen]()
		Button.draw()
		Slider.draw()
	}
